     1→//! Phase 2 Rasterization and Gradient Verification Tests
     2→//!
     3→//! These tests verify the correctness of the rasterization pipeline and gradient computation.
     4→
     5→use sugar_rs::core::{Camera, Gaussian};
     6→use sugar_rs::render::render_full_linear;
     7→use nalgebra::{Matrix3, UnitQuaternion, Vector3};
     8→use std::f32;
