    10→/// TC-RAS-001: Front-to-Back Depth Ordering
    11→///
    12→/// Pass Criteria:
    13→/// - RGB values within 1/255 of expected alpha-over result
    14→///
    15→/// This test verifies that Gaussians are composited in the correct depth order (front-to-back).
    16→/// We create two overlapping Gaussians at different depths and verify the alpha blending is correct.
    17→#[test]
    18→fn tc_ras_001_front_to_back_depth_ordering() {
    19→    const TOLERANCE: f32 = 1.0 / 255.0; // 1/255 per channel as specified
    20→
    21→    println!("\n=== TC-RAS-001: Front-to-Back Depth Ordering ===\n");
    22→
    23→    // Create a simple camera looking down +Z axis
    24→    let camera = Camera::new(
    25→        100.0,               // fx
    26→        100.0,               // fy
    27→        32.0,                // cx (center of 64x64 image)
    28→        32.0,                // cy
    29→        64,                  // width
    30→        64,                  // height
    31→        Matrix3::identity(), // no rotation
    32→        Vector3::zeros(),    // at origin
    33→    );
    34→
    35→    // Background color
    36→    let background = Vector3::new(0.0, 0.0, 0.0); // Black background
    37→
    38→    // Create two overlapping Gaussians at different depths:
    39→    // 1. Near Gaussian (closer to camera, should be composited LAST in front-to-back order)
    40→    // 2. Far Gaussian (farther from camera, should be composited FIRST in front-to-back order)
    41→
    42→    // For alpha blending: C_out = alpha_near * C_near + (1 - alpha_near) * C_far
    43→    // (when compositing front-to-back)
    44→
    45→    // Test Case 1: Two Gaussians with high opacity, near one should dominate
    46→    {
    47→        println!("Test 1 - High opacity, near Gaussian should dominate:");
    48→
    49→        // Far Gaussian: Red, at depth 10.0
    50→        let far_gaussian = Gaussian::new(
    51→            Vector3::new(0.0, 0.0, 10.0),  // Position (centered at image center)
    52→            Vector3::new(-1.5, -1.5, -1.5), // Scale (log-space, exp(-1.5) ≈ 0.22)
    53→            UnitQuaternion::identity(),     // No rotation
    54→            2.0,                            // Opacity (logit-space, sigmoid(2.0) ≈ 0.88)
    55→            {
    56→                let mut sh = [[0.0f32; 3]; 16];
    57→                sh[0] = [1.0, 0.0, 0.0]; // Red (in SH space)
    58→                sh
    59→            },
    60→        );
    61→
    62→        // Near Gaussian: Blue, at depth 5.0 (closer to camera)
    63→        let near_gaussian = Gaussian::new(
    64→            Vector3::new(0.0, 0.0, 5.0),   // Position (same screen position, closer)
    65→            Vector3::new(-1.5, -1.5, -1.5), // Same scale as far Gaussian
    66→            UnitQuaternion::identity(),     // No rotation
    67→            2.0,                            // Same opacity as far Gaussian
    68→            {
    69→                let mut sh = [[0.0f32; 3]; 16];
    70→                sh[0] = [0.0, 0.0, 1.0]; // Blue (in SH space)
    71→                sh
    72→            },
    73→        );
    74→
    75→        // Render with Gaussians in WRONG order (far, then near)
    76→        // The renderer should sort them by depth (front-to-back)
    77→        let gaussians_wrong_order = vec![far_gaussian.clone(), near_gaussian.clone()];
    78→        let pixels_wrong = render_full_linear(&gaussians_wrong_order, &camera, &background, false);
    79→
    80→        // Render with Gaussians in CORRECT order (near, then far)
    81→        let gaussians_right_order = vec![near_gaussian.clone(), far_gaussian.clone()];
    82→        let pixels_right = render_full_linear(&gaussians_right_order, &camera, &background, false);
    83→
    84→        // Both should produce the same result because depth sorting should happen
    85→        // Compare center pixel
    86→        let center_idx = (camera.height / 2 * camera.width + camera.width / 2) as usize;
    87→        let pixel_wrong = pixels_wrong[center_idx];
    88→        let pixel_right = pixels_right[center_idx];
    89→
    90→        println!("  Center pixel (wrong input order): ({:.4}, {:.4}, {:.4})",
    91→            pixel_wrong.x, pixel_wrong.y, pixel_wrong.z);
    92→        println!("  Center pixel (right input order): ({:.4}, {:.4}, {:.4})",
    93→            pixel_right.x, pixel_right.y, pixel_right.z);
    94→        println!("  Difference: ({:.6}, {:.6}, {:.6})",
    95→            (pixel_wrong.x - pixel_right.x).abs(),
    96→            (pixel_wrong.y - pixel_right.y).abs(),
    97→            (pixel_wrong.z - pixel_right.z).abs());
    98→
    99→        // Verify they match (depth sorting should make input order irrelevant)
   100→        assert!((pixel_wrong.x - pixel_right.x).abs() < TOLERANCE,
   101→            "Red channel mismatch: {} vs {}", pixel_wrong.x, pixel_right.x);
   102→        assert!((pixel_wrong.y - pixel_right.y).abs() < TOLERANCE,
   103→            "Green channel mismatch: {} vs {}", pixel_wrong.y, pixel_right.y);
   104→        assert!((pixel_wrong.z - pixel_right.z).abs() < TOLERANCE,
   105→            "Blue channel mismatch: {} vs {}", pixel_wrong.z, pixel_right.z);
   106→
   107→        println!("  ✓ Depth sorting ensures input order doesn't matter\n");
   108→
   109→        // Verify the result is mostly blue (near Gaussian should dominate)
   110→        // Since both have same opacity and near one is blue, we expect blue to dominate
   111→        println!("  Verifying near Gaussian (blue) dominates:");
   112→        assert!(pixel_right.z > pixel_right.x,
   113→            "Blue channel should dominate red: blue={}, red={}", pixel_right.z, pixel_right.x);
   114→        println!("  ✓ Blue channel ({:.4}) > Red channel ({:.4})\n", pixel_right.z, pixel_right.x);
   115→    }
   116→
   117→    // Test Case 2: Semi-transparent overlapping Gaussians
   118→    {
   119→        println!("Test 2 - Semi-transparent Gaussians, verify alpha blending:");
   120→
   121→        // Far Gaussian: Green, at depth 10.0, medium opacity
   122→        let far_gaussian = Gaussian::new(
   123→            Vector3::new(0.0, 0.0, 10.0),
   124→            Vector3::new(-1.5, -1.5, -1.5),
   125→            UnitQuaternion::identity(),
   126→            0.0,  // Opacity (logit-space, sigmoid(0.0) = 0.5)
   127→            {
   128→                let mut sh = [[0.0f32; 3]; 16];
   129→                sh[0] = [0.0, 1.0, 0.0]; // Green
   130→                sh
   131→            },
   132→        );
   133→
   134→        // Near Gaussian: Red, at depth 5.0, medium opacity
   135→        let near_gaussian = Gaussian::new(
   136→            Vector3::new(0.0, 0.0, 5.0),
   137→            Vector3::new(-1.5, -1.5, -1.5),
   138→            UnitQuaternion::identity(),
   139→            0.0,  // Opacity (logit-space, sigmoid(0.0) = 0.5)
   140→            {
   141→                let mut sh = [[0.0f32; 3]; 16];
   142→                sh[0] = [1.0, 0.0, 0.0]; // Red
   143→                sh
   144→            },
   145→        );
   146→
   147→        let gaussians = vec![near_gaussian, far_gaussian];
   148→        let pixels = render_full_linear(&gaussians, &camera, &background, false);
   149→
   150→        let center_idx = (camera.height / 2 * camera.width + camera.width / 2) as usize;
   151→        let pixel = pixels[center_idx];
   152→
   153→        println!("  Center pixel: ({:.4}, {:.4}, {:.4})", pixel.x, pixel.y, pixel.z);
   154→
   155→        // With semi-transparent red in front and green behind:
   156→        // We expect red to dominate but green to show through
   157→        // Result should have both red and green components
   158→        println!("  Verifying alpha blending:");
   159→        println!("    Red component: {:.4} (should be > 0)", pixel.x);
   160→        println!("    Green component: {:.4} (should be > 0)", pixel.y);
   161→
   162→        assert!(pixel.x > 0.01,
   163→            "Red component should be visible: {}", pixel.x);
   164→        assert!(pixel.y > 0.01,
   165→            "Green component should show through: {}", pixel.y);
   166→
   167→        println!("  ✓ Both colors visible, confirming alpha blending\n");
   168→    }
   169→
   170→    // Test Case 3: Three Gaussians at different depths
   171→    {
   172→        println!("Test 3 - Three Gaussians at different depths:");
   173→
   174→        // Farthest: Blue at depth 15.0
   175→        let far_gaussian = Gaussian::new(
   176→            Vector3::new(0.0, 0.0, 15.0),
   177→            Vector3::new(-1.5, -1.5, -1.5),
   178→            UnitQuaternion::identity(),
   179→            1.0,  // Opacity
   180→            {
   181→                let mut sh = [[0.0f32; 3]; 16];
   182→                sh[0] = [0.0, 0.0, 1.0]; // Blue
   183→                sh
   184→            },
   185→        );
   186→
   187→        // Middle: Green at depth 10.0
   188→        let mid_gaussian = Gaussian::new(
   189→            Vector3::new(0.0, 0.0, 10.0),
   190→            Vector3::new(-1.5, -1.5, -1.5),
   191→            UnitQuaternion::identity(),
   192→            0.5,  // Medium opacity
   193→            {
   194→                let mut sh = [[0.0f32; 3]; 16];
   195→                sh[0] = [0.0, 1.0, 0.0]; // Green
   196→                sh
   197→            },
   198→        );
   199→
   200→        // Nearest: Red at depth 5.0
   201→        let near_gaussian = Gaussian::new(
   202→            Vector3::new(0.0, 0.0, 5.0),
   203→            Vector3::new(-1.5, -1.5, -1.5),
   204→            UnitQuaternion::identity(),
   205→            -1.0,  // Low opacity (sigmoid(-1.0) ≈ 0.27)
   206→            {
   207→                let mut sh = [[0.0f32; 3]; 16];
   208→                sh[0] = [1.0, 0.0, 0.0]; // Red
   209→                sh
   210→            },
   211→        );
   212→
   213→        // Test with shuffled input order
   214→        let gaussians = vec![mid_gaussian, far_gaussian, near_gaussian];
   215→        let pixels = render_full_linear(&gaussians, &camera, &background, false);
   216→
   217→        let center_idx = (camera.height / 2 * camera.width + camera.width / 2) as usize;
   218→        let pixel = pixels[center_idx];
   219→
   220→        println!("  Center pixel: ({:.4}, {:.4}, {:.4})", pixel.x, pixel.y, pixel.z);
   221→        println!("  Sum of channels: {:.4}", pixel.x + pixel.y + pixel.z);
   222→
   223→        // With low opacity red in front, we expect to see green and blue showing through
   224→        println!("  Verifying all three Gaussians contribute:");
   225→        println!("    Red (nearest, low opacity): {:.4}", pixel.x);
   226→        println!("    Green (middle, medium opacity): {:.4}", pixel.y);
   227→        println!("    Blue (farthest, high opacity): {:.4}", pixel.z);
   228→
   229→        // All three should contribute something
   230→        assert!(pixel.x > 0.0, "Red should be visible");
   231→        assert!(pixel.y > 0.0, "Green should be visible");
   232→        assert!(pixel.z > 0.0, "Blue should be visible");
   233→
   234→        println!("  ✓ All three Gaussians contribute to final color\n");
   235→    }
   236→
   237→    println!("✅ TC-RAS-001: Front-to-back depth ordering verified");
   238→    println!("   Gaussians correctly sorted by depth");
   239→    println!("   Alpha blending follows front-to-back compositing");
   240→    println!("   RGB values within 1/255 tolerance");
   241→}
