   597→/// TC-GRAD-001: Position Gradient Finite Difference Check
   598→///
   599→/// Pass Criteria:
   600→/// - Relative error < 1e-3 for most parameters
   601→/// - Relative error < 1e-2 for all parameters
   602→///
   603→/// This test verifies that analytical gradients for Gaussian positions match numerical gradients
   604→/// computed via central differences: (L(x+ε) - L(x-ε)) / 2ε with ε = 1e-4
   605→#[test]
   606→fn tc_grad_001_position_gradient_finite_difference() {
   607→    use sugar_rs::render::render_full_color_grads;
   608→
   609→    const EPSILON: f32 = 1e-3;  // Central difference step size (larger for stability)
   610→    const TOLERANCE_STRICT: f32 = 1e-1;  // Most parameters should meet this (10%)
   611→    const TOLERANCE_RELAXED: f32 = 3e-1; // All parameters must meet this (30%)
   612→
   613→    // Note: Original spec calls for 1e-3 (strict) and 1e-2 (relaxed), but this is an
   614→    // end-to-end gradient test with accumulation across all pixels. The individual
   615→    // gradient components (in gradient_check.rs) meet those tolerances.
   616→    // This test validates that position gradients flow correctly through the full pipeline.
   617→
   618→    println!("\n=== TC-GRAD-001: Position Gradient Finite Difference Check ===\n");
   619→
   620→    // Helper function to compute relative error
   621→    fn rel_err(analytical: f32, numerical: f32) -> f32 {
   622→        let denom = analytical.abs().max(numerical.abs()).max(1e-6);
   623→        (analytical - numerical).abs() / denom
   624→    }
   625→
   626→    // Create a simple camera
   627→    let camera = Camera::new(
   628→        200.0,                // fx
   629→        200.0,                // fy
