   631→        32.0,                 // cy
   632→        64,                   // width
   633→        64,                   // height
   634→        Matrix3::identity(),  // no rotation
   635→        Vector3::zeros(),     // at origin
   636→    );
   637→
   638→    let background = Vector3::new(0.1, 0.1, 0.1); // Gray background
   639→
   640→    // Test Case 1: Single Gaussian - basic gradient check
   641→    {
   642→        println!("Test 1 - Single Gaussian position gradient:");
   643→
   644→        // Create a Gaussian with reasonable parameters
   645→        let position = Vector3::new(0.5, 0.3, 5.0);
   646→        let log_scale = Vector3::new(-1.5, -1.5, -1.5); // exp(-1.5) ≈ 0.22
   647→        let rotation = UnitQuaternion::identity();
