   652→            sh
   653→        };
   654→
   655→        let base_gaussian = Gaussian::new(position, log_scale, rotation, opacity, sh_coeffs);
   656→
   657→        // Render with the base Gaussian
   658→        let gaussians = vec![base_gaussian.clone()];
   659→        let base_pixels = render_full_linear(&gaussians, &camera, &background, false);
   660→
   661→        // Create upstream gradient (simulate loss function dL/d(pixel))
   662→        // Use a simple sum of all pixels as the loss
   663→        let d_image: Vec<Vector3<f32>> = vec![Vector3::new(1.0, 1.0, 1.0); base_pixels.len()];
   664→
   665→        // Compute analytical gradients
   666→        let (_img, _colors, _opacities, d_positions, _d_scales, _d_rotations, _d_bg) =
   667→            render_full_color_grads(&gaussians, &camera, &d_image, &background, false);
   668→
   669→        let analytical_grad = d_positions[0];
   670→
   671→        println!("  Base position: ({:.4}, {:.4}, {:.4})", position.x, position.y, position.z);
   672→        println!("  Analytical gradient: ({:.6}, {:.6}, {:.6})",
   673→            analytical_grad.x, analytical_grad.y, analytical_grad.z);
   674→
   675→        // Compute numerical gradients via central differences
   676→        let mut numerical_grad = Vector3::zeros();
   677→
   678→        // X component
   679→        {
   680→            let mut pos_plus = position;
   681→            pos_plus.x += EPSILON;
   682→            let gaussian_plus = Gaussian::new(pos_plus, log_scale, rotation, opacity, sh_coeffs);
