   698→            numerical_grad.x = (loss_plus - loss_minus) / (2.0 * EPSILON);
   699→        }
   700→
   701→        // Y component
   702→        {
   703→            let mut pos_plus = position;
   704→            pos_plus.y += EPSILON;
   705→            let gaussian_plus = Gaussian::new(pos_plus, log_scale, rotation, opacity, sh_coeffs);
   706→            let pixels_plus = render_full_linear(&vec![gaussian_plus], &camera, &background, false);
   707→
   708→            let mut pos_minus = position;
