   723→        // Z component
   724→        {
   725→            let mut pos_plus = position;
   726→            pos_plus.z += EPSILON;
   727→            let gaussian_plus = Gaussian::new(pos_plus, log_scale, rotation, opacity, sh_coeffs);
   728→            let pixels_plus = render_full_linear(&vec![gaussian_plus], &camera, &background, false);
   729→
   730→            let mut pos_minus = position;
