   743→        }
   744→
   745→        println!("  Numerical gradient:  ({:.6}, {:.6}, {:.6})",
   746→            numerical_grad.x, numerical_grad.y, numerical_grad.z);
   747→
   748→        // Compute relative errors
   749→        let rel_err_x = rel_err(analytical_grad.x, numerical_grad.x);
   750→        let rel_err_y = rel_err(analytical_grad.y, numerical_grad.y);
   751→        let rel_err_z = rel_err(analytical_grad.z, numerical_grad.z);
   752→
   753→        println!("  Relative errors:");
   754→        println!("    X: {:.6} (analytical: {:.6}, numerical: {:.6})",
   755→            rel_err_x, analytical_grad.x, numerical_grad.x);
   756→        println!("    Y: {:.6} (analytical: {:.6}, numerical: {:.6})",
   757→            rel_err_y, analytical_grad.y, numerical_grad.y);
   758→        println!("    Z: {:.6} (analytical: {:.6}, numerical: {:.6})",
   759→            rel_err_z, analytical_grad.z, numerical_grad.z);
   760→
   761→        // Verify against tolerances
   762→        assert!(rel_err_x < TOLERANCE_RELAXED,
   763→            "X gradient relative error too large: {} > {}", rel_err_x, TOLERANCE_RELAXED);
   764→        assert!(rel_err_y < TOLERANCE_RELAXED,
   765→            "Y gradient relative error too large: {} > {}", rel_err_y, TOLERANCE_RELAXED);
   766→        assert!(rel_err_z < TOLERANCE_RELAXED,
   767→            "Z gradient relative error too large: {} > {}", rel_err_z, TOLERANCE_RELAXED);
   768→
   769→        let errors_meeting_strict = [rel_err_x, rel_err_y, rel_err_z]
   770→            .iter()
   771→            .filter(|&&e| e < TOLERANCE_STRICT)
   772→            .count();
   773→
   774→        println!("  ✓ All gradients within relaxed tolerance (< {:.0e})", TOLERANCE_RELAXED);
   775→        println!("  ✓ {}/3 gradients within strict tolerance (< {:.0e})\n", errors_meeting_strict, TOLERANCE_STRICT);
   776→    }
