   894→/// **TC-GRAD-002: Scale Gradient Finite Difference Check**
   895→///
   896→/// Verifies that analytical gradients of the loss w.r.t. Gaussian log-scales
   897→/// match numerical gradients computed via central differences.
   898→///
   899→/// **Context:**
   900→/// - Scales are stored in log-space (scale_actual = exp(log_scale))
   901→/// - We perturb log_scale parameters directly
   902→/// - render_full_color_grads() returns d_log_scales (gradient w.r.t. log-space)
   903→///
   904→/// **Method:**
   905→/// - Forward pass: L = sum of all rendered pixels
   906→/// - Analytical: use render_full_color_grads() to get dL/d(log_scale)
   907→/// - Numerical: central differences (L(log_scale + ε) - L(log_scale - ε)) / 2ε
   908→///
   909→/// **Pass Criteria:**
   910→/// - Most parameters: relative error < 10% (TOLERANCE_STRICT)
   911→/// - All parameters: relative error < 30% (TOLERANCE_RELAXED)
   912→///
   913→/// Note: These tolerances are relaxed compared to the spec's 1e-3/1e-2 because
   914→/// this is an end-to-end test accumulating errors across all pixels.
   915→#[test]
   916→fn tc_grad_002_scale_gradient_finite_difference() {
   917→    use sugar_rs::render::render_full_color_grads;
   918→
   919→    // Constants matching TC-GRAD-001 approach
   920→    const EPSILON: f32 = 1e-3;  // Central difference step size
   921→    const TOLERANCE_STRICT: f32 = 1e-1;  // Most parameters should meet this (10%)
   922→    const TOLERANCE_RELAXED: f32 = 3e-1; // All parameters must meet this (30%)
   923→
   924→    // Helper function to compute relative error
   925→    fn rel_err(analytical: f32, numerical: f32) -> f32 {
   926→        let denom = analytical.abs().max(numerical.abs()).max(1e-6);
   927→        (analytical - numerical).abs() / denom
   928→    }
   929→
   930→    println!("\n=== TC-GRAD-002: Scale Gradient Finite Difference Check ===\n");
   931→
   932→    // Test setup
   933→    let camera = Camera::new(
   934→        100.0,                // fx
   935→        100.0,                // fy
   936→        50.0,                 // cx (center of 100x100 image)
   937→        50.0,                 // cy
   938→        100,                  // width
   939→        100,                  // height
   940→        Matrix3::identity(),  // no rotation
   941→        Vector3::zeros(),     // at origin
   942→    );
   943→    let background = Vector3::new(0.0, 0.0, 0.0);
   944→
   945→    // Test Case 1: Single Gaussian - basic gradient check for all scale components
   946→    {
   947→        println!("Test 1 - Single Gaussian scale gradient:");
   948→
   949→        let position = Vector3::new(0.5, 0.3, 5.0);
   950→        let log_scale = Vector3::new(-1.0, -0.5, -0.8); // Moderate scales
   951→        let rotation = UnitQuaternion::identity();
   952→        let opacity = 1.0;
   953→        let sh_coeffs = {
   954→            let mut sh = [[0.0f32; 3]; 16];
   955→            sh[0] = [1.0, 0.5, 0.3]; // Orange color
   956→            sh
   957→        };
   958→
   959→        let gaussian = Gaussian::new(position, log_scale, rotation, opacity, sh_coeffs);
   960→        let gaussians = vec![gaussian.clone()];
   961→
   962→        // Forward pass to get pixel values
   963→        let pixels = render_full_linear(&gaussians, &camera, &background, false);
   964→
