  1219→/// **TC-GRAD-003: Rotation Gradient Finite Difference Check**
  1220→///
  1221→/// Verifies that analytical gradients of the loss w.r.t. Gaussian rotations
  1222→/// match numerical gradients computed via central differences.
  1223→///
  1224→/// **Context:**
  1225→/// - Rotations are stored as unit quaternions
  1226→/// - Gradients are computed w.r.t. rotation vectors (tangent space at current rotation)
  1227→/// - render_full_color_grads() returns d_rot_vecs (gradient w.r.t. rotation vector ω)
  1228→/// - Small rotation vector ω perturbs rotation: R_perturbed = exp(ω) * R_base (left multiply)
  1229→///
  1230→/// **Method:**
  1231→/// - Forward pass: L = sum of all rendered pixels
  1232→/// - Analytical: use render_full_color_grads() to get dL/dω
  1233→/// - Numerical: central differences with tangent space perturbation
  1234→///   - R_plus = exp(ε * e_i) * R_base where e_i is unit vector along axis i
  1235→///   - R_minus = exp(-ε * e_i) * R_base
  1236→///   - dL/dω_i = (L(R_plus) - L(R_minus)) / 2ε
  1237→///
  1238→/// **Pass Criteria:**
  1239→/// - Most parameters: relative error < 10% (TOLERANCE_STRICT)
  1240→/// - All parameters: relative error < 30% (TOLERANCE_RELAXED)
  1241→///
  1242→/// Note: These tolerances are relaxed compared to the spec's 1e-3/1e-2 because
  1243→/// this is an end-to-end test accumulating errors across all pixels.
  1244→#[test]
  1245→fn tc_grad_003_rotation_gradient_finite_difference() {
  1246→    use sugar_rs::render::render_full_color_grads;
  1247→
  1248→    // Constants matching TC-GRAD-001 and TC-GRAD-002 approach
  1249→    const EPSILON: f32 = 1e-3;  // Central difference step size
  1250→    const TOLERANCE_STRICT: f32 = 1e-1;  // Most parameters should meet this (10%)
  1251→    const TOLERANCE_RELAXED: f32 = 3e-1; // All parameters must meet this (30%)
  1252→
  1253→    // Helper function to compute relative error
  1254→    fn rel_err(analytical: f32, numerical: f32) -> f32 {
  1255→        let denom = analytical.abs().max(numerical.abs()).max(1e-6);
  1256→        (analytical - numerical).abs() / denom
  1257→    }
  1258→
  1259→    // Helper to apply a small rotation vector to a base rotation
  1260→    // R_new = exp(omega) * R_base (left-hand perturbation)
  1261→    // For small omega, exp(omega) ≈ UnitQuaternion::new(omega)
  1262→    // This matches the gradient computation which uses dR/dω = K_i * R
  1263→    fn apply_rotation_vector(base: &UnitQuaternion<f32>, omega: Vector3<f32>) -> UnitQuaternion<f32> {
  1264→        let delta_rot = UnitQuaternion::new(omega);
  1265→        delta_rot * base
  1266→    }
