  1275→        50.0,                 // cy
  1276→        100,                  // width
  1277→        100,                  // height
  1278→        Matrix3::identity(),  // no rotation
  1279→        Vector3::zeros(),     // at origin
  1280→    );
  1281→    let background = Vector3::new(0.0, 0.0, 0.0);
  1282→
