    11→pub mod simple;
    12→
    13→// Re-export
    14→pub use full::FullRenderer;
    15→pub use full_diff::{render_full_color_grads, render_full_linear};
    16→pub use simple::SimpleRenderer;
    17→
    18→// TODO: Implement full renderer for M4-M5
